import numpy as np
from typing import List, Callable

# --- Placeholder encoders (swap with SigLIP/OpenCLIP in production) ---
def clip_encode_frames(frames: np.ndarray) -> np.ndarray:
    # frames: [N, H, W, 3] -> [N, D]; deterministic fake encoder for demo
    rng = np.random.default_rng(0)
    return rng.standard_normal((len(frames), 512)).astype(np.float32)

def clip_encode_text(query: str) -> np.ndarray:
    rng = np.random.default_rng(abs(hash(query)) % (2**32))
    return rng.standard_normal(512).astype(np.float32)

def cosine(a: np.ndarray, b: np.ndarray) -> np.ndarray:
    a = a / (np.linalg.norm(a, axis=-1, keepdims=True) + 1e-8)
    b = b / (np.linalg.norm(b) + 1e-8)
    return a @ b  # [N]

# --- AKS recursive partition core ---
def aks_partition(scores: np.ndarray, lo: int, hi: int, k: int,
                  uniform_fallback_std: float = 1e-3) -> List[int]:
    """Select k indices from scores[lo:hi] balancing relevance and coverage."""
    span = scores[lo:hi]
    if k <= 0 or len(span) == 0:
        return []
    # Fallback: if the partition is too flat, query is uninformative here.
    if span.std() < uniform_fallback_std or k >= len(span):
        step = max(len(span) // max(k, 1), 1)
        return [lo + i * step for i in range(k) if lo + i * step < hi]
    if k == 1:
        return [lo + int(np.argmax(span))]
    mid = lo + len(span) // 2
    left_k, right_k = k // 2, k - k // 2
    return (aks_partition(scores, lo, mid, left_k, uniform_fallback_std)
            + aks_partition(scores, mid, hi, right_k, uniform_fallback_std))

def aks_select(frames: np.ndarray, query: str, k: int = 8) -> List[int]:
    frame_emb = clip_encode_frames(frames)            # [N, D]
    query_emb = clip_encode_text(query)               # [D]
    scores = cosine(frame_emb, query_emb)             # [N]
    idx = aks_partition(scores, 0, len(scores), k)
    return sorted(idx)

if __name__ == "__main__":
    fake_video = np.zeros((200, 224, 224, 3), dtype=np.uint8)
    picked = aks_select(fake_video, "person opens a red door", k=8)
    print("selected frame indices:", picked)

from __future__ import annotations
from dataclasses import dataclass
from typing import Protocol, runtime_checkable
import numpy as np

@dataclass
class VideoHandle:
    video_id: str
    fps: float
    num_frames: int
    # lazy reader: get_frame(idx) -> np.ndarray[H, W, 3]
    get_frame: callable

@dataclass
class Scene:
    start: int
    end: int  # inclusive

@runtime_checkable
class Sampler(Protocol):
    """Plug-and-play contract: returns frame indices, never frames."""
    name: str

    def select(
        self,
        video: VideoHandle,
        query: str | None,
        budget: int,
        scenes: list[Scene] | None = None,
    ) -> list[int]: ...

class UniformSampler:
    name = "uniform"
    def select(self, video, query, budget, scenes=None):
        if budget >= video.num_frames:
            return list(range(video.num_frames))
        idx = np.linspace(0, video.num_frames - 1, budget, dtype=int)
        return idx.tolist()

class AKSampler:
    """Stub of AKS (CVPR 2025, arXiv:2502.21271).
    Real impl: SigLIP scoring + relevance/coverage adaptive split."""
    name = "aks"
    def __init__(self, scorer): self.scorer = scorer
    def select(self, video, query, budget, scenes=None):
        assert query is not None, "AKS is query-aware"
        # 1) score all frames vs query (cached in production)
        scores = self.scorer.score(video, query)  # shape [T]
        # 2) adaptive top-k with coverage constraint over scenes
        anchors = [s.start for s in (scenes or [])]
        return _adaptive_topk(scores, budget, anchors)

class BoltSampler:
    """Stub of BOLT (CVPR 2025, arXiv:2503.21483).
    Real impl: inverse-transform sampling on query-frame alignment."""
    name = "bolt"
    def __init__(self, scorer): self.scorer = scorer
    def select(self, video, query, budget, scenes=None):
        assert query is not None
        weights = self.scorer.score(video, query)
        cdf = np.cumsum(np.clip(weights, 1e-6, None))
        cdf /= cdf[-1]
        us = (np.arange(budget) + 0.5) / budget
        idx = np.searchsorted(cdf, us)
        return np.clip(idx, 0, video.num_frames - 1).tolist()

def _adaptive_topk(scores, budget, anchors):
    # simplified: take all anchors then top-k by score for remainder
    base = sorted(set(anchors))[:budget]
    if len(base) >= budget: return base[:budget]
    remaining = budget - len(base)
    ranked = np.argsort(-scores).tolist()
    extra = [i for i in ranked if i not in set(base)][:remaining]
    return sorted(base + extra)

# ---- The pipeline calls them interchangeably ----
def run_pipeline(video: VideoHandle, query: str, sampler: Sampler,
                 encoder, llm, budget: int = 64) -> str:
    assert isinstance(sampler, Sampler), "contract violation"
    indices = sampler.select(video, query=query, budget=budget)
    frames = np.stack([video.get_frame(i) for i in indices])
    vision = encoder.encode(frames)              # Tensor[N, D_v]
    return llm.generate(query, vision_tokens=vision)
